import React, { useState, useEffect, useCallback } from 'react';
import { Link } from 'react-router-dom';

const API_KEY = 'YOUR_YOUTUBE_API_KEY'; 

function Home() {
  const [showBanner, setShowBanner] = useState(true);
  const [activeTab, setActiveTab] = useState('Home');
  const [searchQuery, setSearchQuery] = useState('');
  const [videos, setVideos] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [nextPageToken, setNextPageToken] = useState('');

  
  const fetchVideos = async (query = 'programming tutorials', pageToken = '') => {
    setIsLoading(true);
    try {
      const url = `https://www.googleapis.com/youtube/v3/search?part=snippet&maxResults=12&q=${encodeURIComponent(
        query
      )}&type=video&key=${API_KEY}${pageToken ? `&pageToken=${pageToken}` : ''}`;

      const response = await fetch(url);
      const data = await response.json();

      if (data.items) {
        const formattedVideos = data.items.map((item) => ({
          id: item.id.videoId,
          title: item.snippet.title,
          thumbnailUrl: item.snippet.thumbnails.high.url,
          channelLogo: item.snippet.thumbnails.default.url,
          channelName: item.snippet.channelTitle,
          views: 'Live Stream/Video',
          publishedAt: new Date(item.snippet.publishedAt).toLocaleDateString()
        }));

        setVideos((prev) => (pageToken ? [...prev, ...formattedVideos] : formattedVideos));
        setNextPageToken(data.nextPageToken || '');
      }
    } catch (error) {
      console.error('Error fetching videos:', error);
    } finally {
      setIsLoading(false);
    }
  };

  
  useEffect(() => {
    fetchVideos('coding tutorials');
  }, []);

  
  const handleSearchSubmit = (e) => {
    e.preventDefault();
    if (searchQuery.trim()) {
      fetchVideos(searchQuery);
    }
  };

  
  const loadMoreVideos = useCallback(() => {
    if (!isLoading && nextPageToken) {
      fetchVideos(searchQuery || 'coding tutorials', nextPageToken);
    }
  }, [isLoading, nextPageToken, searchQuery]);

  useEffect(() => {
    const handleScroll = () => {
      if (
        window.innerHeight + document.documentElement.scrollTop + 200 >=
        document.documentElement.offsetHeight
      ) {
        loadMoreVideos();
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, [loadMoreVideos]);

  return (
    <div className="nxt-layout">
      
      <aside className="nxt-sidebar">
        <nav className="sidebar-menu">
          <button
            className={`menu-item ${activeTab === 'Home' ? 'active' : ''}`}
            onClick={() => {
              setActiveTab('Home');
              fetchVideos('coding tutorials');
            }}
          >
            <span className="icon">🔴</span> Home
          </button>
          <button
            className={`menu-item ${activeTab === 'Trending' ? 'active' : ''}`}
            onClick={() => {
              setActiveTab('Trending');
              fetchVideos('trending tech videos');
            }}
          >
            <span className="icon">🔥</span> Trending
          </button>
          <button
            className={`menu-item ${activeTab === 'Gaming' ? 'active' : ''}`}
            onClick={() => {
              setActiveTab('Gaming');
              fetchVideos('gaming trailers 2026');
            }}
          >
            <span className="icon">🎮</span> Gaming
          </button>
          <Link to="/notes" className="menu-item">
            <span className="icon">📑</span> Saved Videos
          </Link>
        </nav>

        <div className="sidebar-footer">
          <p className="footer-heading">CONTACT US</p>
          <div className="social-icons">
            <span className="social-btn fb">f</span>
            <span className="social-btn tw">t</span>
            <span className="social-btn in">in</span>
          </div>
          <p className="footer-text">Enjoy! Now to see your channels and recommendations!</p>
        </div>
      </aside>

      
      <main className="nxt-main">
        {showBanner && (
          <div className="promo-banner">
            <div className="banner-content">
              <span className="banner-logo">LearnStream</span>
              <p>Buy LearnStream Premium prepaid plans with UPI</p>
              <button className="banner-btn">GET IT NOW</button>
            </div>
            <button className="banner-close" onClick={() => setShowBanner(false)}>
              ✕
            </button>
          </div>
        )}

        
        <div className="search-section">
          <form onSubmit={handleSearchSubmit} className="search-box">
            <input
              type="text"
              placeholder="Search any topic or video..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
            <button type="submit" className="search-btn">
              🔍
            </button>
          </form>
        </div>

        
        <div className="nxt-video-grid">
          {videos.map((video, index) => (
            <Link key={`${video.id}-${index}`} to={`/video/${video.id}`} className="nxt-video-card">
              <img src={video.thumbnailUrl} alt={video.title} className="card-thumb" />
              <div className="card-details">
                <img src={video.channelLogo} alt={video.channelName} className="channel-avatar" />
                <div className="card-info">
                  <h4 className="video-title">{video.title}</h4>
                  <p className="channel-title">{video.channelName}</p>
                  <p className="video-meta">{video.publishedAt}</p>
                </div>
              </div>
            </Link>
          ))}
        </div>

        {isLoading && (
          <div style={{ textAlign: 'center', padding: '20px 0', color: '#64748b' }}>
            <p>Loading results...</p>
          </div>
        )}
      </main>
    </div>
  );
}

export default Home;
